/* Dated capital roles; city anchors indicate urban areas, not palace footprints. */
(function(scope){
'use strict';
let data={entries:[],sources:{}},moves=[],stop=()=>{};
const esc=s=>String(s??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const year=n=>n<0?'公元前'+(-n)+'年':n+'年';
const active=y=>data.entries.filter(e=>y>=e.from&&y<=e.to);
const key=y=>active(y).map(e=>e.id).concat(moves.filter(e=>e.year===y).map(e=>'move:'+e.id)).join('|');
const isPlace=(modern,y)=>active(y).some(e=>e.modern===modern);
function init(input,context){data=input;moves=context.moves||[];stop=context.stop;}
function open(e){stop();const dialog=document.getElementById('capitalDialog');document.getElementById('capitalTitle').textContent=e.name+' · '+e.role;document.getElementById('capitalRange').textContent=e.dynasty+' ｜ '+year(e.from)+' — '+year(e.to);document.getElementById('capitalNote').textContent=e.note;document.getElementById('capitalSources').innerHTML=e.sourceIds.map(id=>data.sources[id]).filter(Boolean).map(s=>'<p><a href="'+esc(s.url)+'" target="_blank" rel="noopener">'+esc(s.title)+' ↗</a></p>').join('');dialog.showModal();}
function drawMoves(root,projection,y){for(const event of moves.filter(e=>e.year===y)){const m=event.capitalMove;if(!['move','return','seat'].includes(m.kind))continue;const a=projection(m.from.point),b=projection(m.to.point),dx=b[0]-a[0],dy=b[1]-a[1],length=Math.hypot(dx,dy);if(length<12)continue;const end=[b[0]-dx/length*9,b[1]-dy/length*9],control=[(a[0]+b[0])/2-dy*.12,(a[1]+b[1])/2+dx*.12],layer=root.append('g').attr('class','capital-move-layer').attr('data-capital-move',event.id).attr('role','img').attr('aria-label',m.polity+'：'+m.from.label+' → '+m.to.label+'（方向示意）');layer.append('title').text(event.title+'；'+m.geometryNote);layer.append('path').attr('d','M'+a+' Q'+control+' '+end).attr('class','capital-move-path').attr('marker-end','url(#capitalMoveArrow)');layer.append('circle').attr('cx',a[0]).attr('cy',a[1]).attr('r',4).attr('class','capital-move-origin');}}
function draw(root,projection,y,options){drawMoves(root,projection,y);const layer=root.append('g').attr('class','capital-layer'),k=Number(root.style('--city-zoom'))||1,entries=active(y);for(const e of entries){const p=projection(e.point);if(!p||p[0]<12||p[0]>options.width-12||p[1]<15||p[1]>options.height-35)continue;const primary=['都城','王都'].includes(e.role),fullLabel=e.name+' · '+e.role,label=primary&&entries.filter(other=>other.dynasty===e.dynasty).length===1?e.name:fullLabel,w=label.length*9.6+12;let offset=[11,-10];for(const [dx,dy] of [[11,-10],[11,17],[-w-11,-10],[-w-11,17],[11,-30]]){const box=[p[0]+dx-3,p[1]+dy-13,p[0]+dx+w,p[1]+dy+4];if(box[0]<8||box[2]>options.width-8||box[1]<10||box[3]>options.height-40||options.reserved.some(b=>b[0]<box[2]&&b[2]>box[0]&&b[1]<box[3]&&b[3]>box[1]))continue;offset=[dx,dy];break;}const g=layer.append('g').attr('class','capital-marker '+(primary?'capital-primary':'capital-secondary')).attr('data-capital-id',e.id).attr('transform','translate('+p[0]+','+p[1]+')').attr('role','button').attr('tabindex',0).attr('aria-label',e.dynasty+'，'+fullLabel+'，查看都城依据').on('click',event=>{event.stopPropagation();open(e);}).on('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();event.stopPropagation();open(e);}});const inner=g.append('g').attr('class','capital-symbol').attr('transform','scale('+1/k+')');inner.append('circle').attr('r',7.5).attr('class','capital-halo');inner.append('path').attr('d','M0-6 1.8-1.9 6.2-1.9 2.9 .9 3.8 5.3 0 2.8-3.8 5.3-2.9 .9-6.2-1.9-1.8-1.9Z').attr('class','capital-star');inner.append('rect').attr('x',offset[0]-4).attr('y',offset[1]-11).attr('width',w).attr('height',16).attr('rx',3).attr('class','capital-label-bg');inner.append('text').attr('x',offset[0]+1).attr('y',offset[1]+.5).attr('class','capital-label').text(label);inner.append('title').text(e.dynasty+' · '+fullLabel+'\n'+e.note);options.reserved.push([p[0]+offset[0]-5,p[1]+offset[1]-14,p[0]+offset[0]+w,p[1]+offset[1]+7]);}}
scope.CapitalContext={init,active,key,isPlace,draw};if(typeof module!=='undefined')module.exports=scope.CapitalContext;
})(globalThis);
